#
# Normalizes the configured OIDC signing key into a PEM string that OpenSSL can
# parse, so the same key can be supplied in two convenient forms:
#
#   * as a full multi-line PEM with BEGIN/END gating (e.g. in config/config.yml):
#       -----BEGIN EC PRIVATE KEY-----
#       MIHcAgEBBEIA...
#       -----END EC PRIVATE KEY-----
#
#   * as a single flat string with no gating and no line breaks (e.g. from the
#     OPENID_PRIVATE_KEY env var, as generated by `rake dawa:required`):
#       MIHcAgEBBEIA...
#
# A flat string is re-wrapped into a proper PEM (gated and newlined every 64
# characters) so `signing_key` and the tests always hand OpenSSL a parseable key.
#
module Dawa
  module OidcKey
    # Width PEM body lines are wrapped to, per RFC 7468 / OpenSSL's output.
    LINE_WIDTH = 64

    # Given the raw configured value, return a parseable PEM string.
    def self.to_pem(value)
      return "" if value.blank?

      raw = value.to_s
      # If the value survived a `.env`-style front that escaped newlines as
      # literal backslash-n, restore them.
      raw = raw.gsub("\\n", "\n") if raw.include?("\\n")
      raw = raw.strip

      # Already a complete, gated, multi-line PEM: hand it through unchanged.
      return raw + "\n" if complete_pem?(raw)

      body = extract_body(raw)
      return "" if body.empty?

      type = detect_type(body)
      wrapped = body.scan(/.{1,#{LINE_WIDTH}}/).join("\n")
      "-----BEGIN #{type}PRIVATE KEY-----\n#{wrapped}\n-----END #{type}PRIVATE KEY-----\n"
    end

    # True when the string already looks like a gated, newlined PEM.
    def self.complete_pem?(raw)
      raw.match?(/\A-----BEGIN (?:RSA |EC |DSA )?PRIVATE KEY-----/) &&
        raw.include?("\n") &&
        raw.end_with?("-----END")
    end

    def self.extract_body(raw)
      if (m = raw.match(/-----BEGIN .*?PRIVATE KEY-----(.*?)-----END .*?PRIVATE KEY-----/m))
        m[1]
      else
        raw
      end.gsub(/\s+/, "")
    end

    # Determine the key type from the (assumed DER) body so the correct PEM
    # header is used. Falls back to EC (Dawa signs with P-521/ES512).
    def self.detect_type(body)
      decoded = begin
        OpenSSL::PKey.read(Base64.decode64(body))
      rescue StandardError
        nil
      end
      case decoded
      when OpenSSL::PKey::RSA then "RSA "
      when OpenSSL::PKey::EC then "EC "
      else ""
      end
    end
    private_class_method :complete_pem?, :extract_body, :detect_type
  end
end
